const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines=v=>String(v||'').split(/\n+/).filter(Boolean);
const para=v=>String(v||'').split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',up:'M6 18 18 6M6 6h12v12',chevron:'m7 10 5 5 5-5',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',users:'M16 21v-2a5 5 0 0 0-10 0v2M15 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM19 8a3 3 0 0 1 0 6m2 7v-2a4 4 0 0 0-3-4',lock:'M6 10h12v11H6ZM8 10V6a4 4 0 0 1 8 0v4',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',book:'M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1Zm0 0v15',library:'M4 4h3v17H4ZM10 4h3v17h-3ZM16 5l3-1 4 16-3 1Z',landmark:'m3 9 9-6 9 6H3ZM5 10v9m7-9v9m7-9v9M3 21h18',building:'M4 21V5l8-3v19M12 8h8v13M7 7v1m0 4v1m0 4v1m9-6v1m0 4v1M2 21h20',leaf:'M20 3C8 2 2 9 5 16s15 4 15-13ZM5 20 15 10',heart:'M20 4c-3-2-6 0-8 3-2-3-5-5-8-3-5 4 1 11 8 17 7-6 13-13 8-17Z',briefcase:'M3 7h18v14H3ZM8 7V3h8v4M3 12c6 4 12 4 18 0m-9 1v4',map:'m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3Zm6-3v17m6-14v17',message:'M21 4H3v14h4v4l6-4h8ZM7 9h10M7 13h7',file:'M5 2h9l5 5v15H5ZM14 2v6h5M8 13h8m-8 4h8',film:'M3 3h18v18H3ZM7 3v18m10-18v18M3 7h4m-4 5h4m-4 5h4M17 7h4m-4 5h4m-4 5h4',play:'m9 5 11 7-11 7Z',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3Zm0 0 9 8 9-8',phone:'M5 3h4l2 5-3 2c2 4 4 6 6 7l2-3 5 2v4c-9 4-21-10-16-17Z',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 1 1 16 0ZM15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',grid:'M3 3h7v7H3Zm11 0h7v7h-7ZM3 14h7v7H3Zm11 0h7v7h-7Z',edit:'m4 15 12-12 5 5L9 20l-6 1Zm10-10 5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',plus:'M12 4v16M4 12h16',upload:'M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6',download:'M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5',image:'M3 3h18v18H3Zm0 14 6-6 6 6 3-3 3 3M17 7h.01',settings:'m12 3 2 3 4-1 1 4 3 3-3 2-1 4-4 1-2 3-2-3-4-1-1-4-3-2 3-3 1-4 4 1ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',palette:'M12 3a9 9 0 1 0 0 18c4 0 2-4 4-5s5 0 5-4a9 9 0 0 0-9-9ZM8 8h.01M13 6h.01M17 10h.01M7 13h.01',logout:'M10 3H3v18h7m4-15 6 6-6 6m-6-6h12',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7ZM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',eyeoff:'m3 3 18 18M6 6c-2 2-4 6-4 6s4 7 10 7c2 0 4-1 6-3M9 5c1 0 2 0 3 0 6 0 10 7 10 7l-3 4',calendar:'M3 5h18v16H3ZM7 2v6m10-6v6M3 10h18m-14 4h2m4 0h2m-8 4h2m4 0h2',copy:'M8 8h13v13H8ZM4 16H2V2h14v2',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c-6 5-6 15 0 20 6-5 6-15 0-20Z',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',folder:'M2 6h7l2 3h11v12H2ZM2 6V3h7l2 3h9v3',history:'M3 12a9 9 0 1 1 3 7M3 4v8h8m1-6v7l4 2',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7'};
const icon=(n,small=false)=>`<svg class="icon${small?' small':''}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const LABELS={berita:'Berita',pengumuman:'Pengumuman',agenda:'Agenda',entitas:'Entitas Kebudayaan',cinebudaya:'Cinebudaya',publikasi:'Publikasi',ppid:'PPID',sakip:'SAKIP',peraturan:'Peraturan',galeri:'Galeri'};
const ROLE_LABELS={superadmin:'Superadmin',admin:'Admin',editor:'Editor konten',operator:'Petugas layanan'};
const STATUSES=['Diterima','Diverifikasi','Perlu Perbaikan','Diproses','Selesai','Ditolak'];
let S={settings:{},posts:[],services:[],user:null,csrf:'',adminPosts:[],adminServices:[],requests:[],media:[],users:[],audit:[],filters:{},page:1};
let routeVersion=0,lastTicket=null,tracked=null,timer=null;
async function api(path,opts={}){
 if(window.BPK_PREVIEW)return window.previewAPI(path,opts);
 const headers={...(opts.headers||{})};if(opts.body instanceof FormData){}else if(opts.body!==undefined){headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body);}
 if(opts.method&&opts.method!=='GET')headers['X-CSRF-Token']=S.csrf;
 const res=await fetch('/api'+path,{...opts,headers,credentials:'same-origin'});
 if(!res.ok){let msg='Terjadi kendala. Coba kembali.';try{const d=await res.json();msg=typeof d.detail==='string'?d.detail:msg;}catch{}throw new Error(msg);}
 if(opts.blob)return res.blob();return res.json();
}
async function refresh(){const d=await api('/public');Object.assign(S,d);applyTheme();}
function setSession(r){S.user=r.user;S.csrf=r.csrf||S.csrf;}
function go(path){location.hash=path;}
function urlSafe(value,{image=false}={}){
 const v=String(value||'');if(!v)return '';
 if(v.startsWith('/files/')||v.startsWith('/static/assets/'))return v;
 if(window.BPK_PREVIEW&&image&&/^data:image\/(webp|png|jpeg);base64,/i.test(v))return v;
 if(window.BPK_PREVIEW&&v.startsWith('demo-file:'))return window.previewFile(v);
 try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}
}
function contrast(hex){let c=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722>.35?'#2a211a':'#ffffff';}
function applyTheme(custom={}){const s={...S.settings,...custom};for(const [key,css]of[['primary_color','primary'],['accent_color','accent'],['background_color','bg']])if(/^#[0-9a-f]{6}$/i.test(s[key]||'')){document.documentElement.style.setProperty('--'+css,s[key]);document.documentElement.style.setProperty('--'+css+'-text',contrast(s[key]));}document.title=S.settings.site_name||'Balai Pelestarian Kebudayaan Kaltim';}
function date(t,short=false){if(!t)return 'Belum ditentukan';let d=new Date(t);return isNaN(d)?esc(t):new Intl.DateTimeFormat('id-ID',{day:'numeric',month:short?'short':'long',year:'numeric',timeZone:'Asia/Makassar'}).format(d);}
function dateTime(t){return date(t,true)+' · '+new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Makassar'}).format(new Date(t))+' WITA';}
function bytes(n){return n<1024*1024?(n/1024).toFixed(0)+' KB':(n/1024/1024).toFixed(1)+' MB';}
function status(t){return `<span class="status ${esc(t.toLowerCase().replaceAll(' ','-'))}">${esc(t==='published'?'Terbit':t==='draft'?'Draf':t==='active'?'Aktif':t==='inactive'?'Nonaktif':t)}</span>`;}
function badge(p){return p.is_demo?'<span class="demo-badge">Konten contoh</span>':'';}
function abstract(){return '<div class="art-abstract" aria-hidden="true"><div class="arch"></div><div class="woven"></div></div>';}
function thumbnail(p,i=0){let src=urlSafe(p.image,{image:true});return `<div class="thumb thumb-${i%3+1}">${src?`<img src="${esc(src)}" alt="${esc(p.title)}" loading="lazy">`:abstract()}<span class="thumb-label">${esc(p.category||LABELS[p.kind]||'Kebudayaan')}</span><span class="thumb-mark">${icon(p.kind==='cinebudaya'?'play':'up',true)}</span></div>`;}
function card(p,i=0){return `<a class="story-card" href="#konten/${p.id}">${thumbnail(p,i)}<div class="card-body"><div class="meta">${esc(p.category||LABELS[p.kind])}${badge(p)}</div><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p></div><div class="card-bottom"><span>${p.is_demo?'Pratinjau editorial':date(p.event_date||p.created_at,true)}</span>${icon('arrow',true)}</div></a>`;}
function empty(title,message,ic='folder',action=''){return `<div class="empty">${icon(ic)}<h3>${esc(title)}</h3><p>${esc(message)}</p>${action}</div>`;}
function field(name,label,value='',type='text',opts={}){let id=opts.id||'f-'+name;return `<div class="field ${opts.full?'full':''}"><label for="${esc(id)}">${esc(label)}${opts.required?' <span aria-hidden="true">*</span>':''}</label>${type==='textarea'?`<textarea id="${esc(id)}" name="${esc(name)}" ${opts.required?'required':''} ${opts.rows?`rows="${opts.rows}"`:''} ${opts.long?'class="long"':''} maxlength="${opts.max||100000}">${esc(value)}</textarea>`:`<input id="${esc(id)}" type="${type}" name="${esc(name)}" value="${esc(value)}" ${opts.required?'required':''} ${opts.readonly?'readonly':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''} ${type!=='color'&&type!=='file'?`maxlength="${opts.max||2000}"`:''}>`}${opts.help?`<small>${esc(opts.help)}</small>`:''}</div>`;}
function select(name,label,value,items,opts={}){return `<div class="field ${opts.full?'full':''}"><label for="f-${esc(name)}">${esc(label)}</label><select name="${esc(name)}" id="f-${esc(name)}" ${opts.required?'required':''}>${items.map(it=>{let v=Array.isArray(it)?it[0]:it,t=Array.isArray(it)?it[1]:it;return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></div>`;}
function passwordField(name,label,autocomplete='current-password'){return `<div class="field"><label for="f-${name}">${esc(label)}</label><div class="password-wrap"><input id="f-${name}" type="password" name="${name}" autocomplete="${autocomplete}" required maxlength="128"><button type="button" class="eye-button" data-action="eye" data-target="f-${name}" aria-label="Tampilkan kata sandi">${icon('eye')}</button></div></div>`;}
function check(name,label,checked=false){return `<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}> <span>${label}</span></label>`;}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error-toast':'');clearTimeout(timer);timer=setTimeout(()=>t.className='',4500);}
function showModal(title,body){$('#modal-inner').innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" data-action="close-modal" aria-label="Tutup dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function actionButton(action,title,ic,id,extra=''){return `<button type="button" class="icon-btn ${action.includes('delete')?'delete':''}" data-action="${action}" data-id="${id}" title="${esc(title)}" aria-label="${esc(title)}" ${extra}>${icon(ic)}</button>`;}
function header(active){const s=S.settings;const today=date(new Date(),true);const logo=urlSafe(s.logo_url,{image:true});return `<div class="topbar"><div class="container"><p>Kementerian Kebudayaan Republik Indonesia</p><div class="right"><span class="date-label">${today}</span><span><i class="tiny-dot"></i>Kalimantan Timur · WITA</span></div></div></div><header class="site-header"><div class="container nav-wrap"><a class="brand" href="#beranda" aria-label="Beranda ${esc(s.site_name)}">${logo?`<img class="brand-logo" src="${esc(logo)}" alt="Logo Kementerian Kebudayaan Republik Indonesia">`:''}<span class="brand-divider"></span><span class="brand-name">${esc(s.site_name)}<small>Merawat keberagaman</small></span></a><a class="mobile-login login-btn" href="${S.user?'#admin/dashboard':'#login'}" aria-label="${S.user?'Panel Admin':'Login admin'}">${icon('user',true)}<span>${S.user?'Admin':'Login'}</span></a><button type="button" class="menu-button" data-action="toggle-nav" aria-label="Buka menu" aria-expanded="false">${icon('menu')}</button><nav class="nav-links" aria-label="Navigasi utama"><a class="${active==='beranda'?'active':''}" href="#beranda">Beranda</a><a class="${active==='profil'?'active':''}" href="#profil">Profil</a><a class="${active==='layanan'?'active':''}" href="#layanan">Layanan</a><a class="optional-nav ${active==='entitas'?'active':''}" href="#entitas">Jelajah Budaya</a><a class="${active==='cinebudaya'?'active':''}" href="#cinebudaya">Cinebudaya</a><details><summary>Informasi ${icon('chevron',true)}</summary><div class="dropdown"><a href="#entitas">Entitas Kebudayaan</a><a href="#berita">Kabar & Pengumuman</a><a href="#agenda">Agenda Budaya</a><a href="#publikasi">Publikasi & Perpustakaan</a><a href="#ppid">PPID</a><a href="#sakip">SAKIP</a><a href="#peraturan">Peraturan</a><a href="#galeri">Galeri</a><a href="#kontak">Kontak & Bantuan</a></div></details><a class="login-btn" href="${S.user?'#admin/dashboard':'#login'}">${icon('user',true)}${S.user?'Panel Admin':'Login'}</a></nav></div></header>${window.BPK_PREVIEW?'<div class="review-bar"><b>PRATINJAU LOKAL</b> · Data percobaan hanya disimpan di browser ini, bukan dikirim ke balai. <a href="#sumber">Tentang pratinjau</a></div>':s.review_mode?'<div class="review-bar">MODE PENINJAUAN · Konten dan standar layanan menunggu pengesahan balai. Pengajuan pada mode ini adalah data uji.</div>':''}`;}
function footer(){const s=S.settings;return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="#beranda"><span class="brand-name">${esc(s.site_name)}</span></a><p>Merawat warisan, membuka ruang perjumpaan, dan menghidupkan kebudayaan bersama masyarakat.</p></div><div><h4>Jelajahi</h4><div class="footer-links"><a href="#profil">Tentang Balai</a><a href="#entitas">Entitas Kebudayaan</a><a href="#cinebudaya">Cinebudaya</a><a href="#berita">Kabar Budaya</a><a href="#agenda">Agenda</a></div></div><div><h4>Akses layanan</h4><div class="footer-links"><a href="#layanan">Portal Layanan</a><a href="#lacak">Lacak Permohonan</a><a href="#ppid">Informasi Publik</a><a href="#sakip">Akuntabilitas Kinerja</a><a href="#peraturan">Peraturan</a></div></div><div><h4>Terhubung dengan kami</h4>${s.address?`<p>${esc(s.address)}</p>`:'<p class="footer-contact-note">Alamat dan kontak resmi dapat dilengkapi pengelola melalui panel admin.</p>'}<div class="footer-links mt">${s.email?`<a href="mailto:${esc(s.email)}">${esc(s.email)}</a>`:''}${s.phone?`<span>${esc(s.phone)}</span>`:''}<a href="#kontak">Kontak & bantuan ${icon('up',true)}</a></div></div></div><div class="footer-base"><div>© ${new Date().getFullYear()} ${esc(s.site_name)}.</div><div><a href="#privasi">Privasi</a> &nbsp; / &nbsp; <a href="#sumber">Sumber & kredit</a> &nbsp; / &nbsp; <a href="#login">Login pengelola</a></div></div></div></footer>`;}
function publicLayout(content,active=''){return header(active)+`<main id="main" tabindex="-1">${content}</main>`+footer();}
function pageHead(title,desc='',parent=''){return `<section class="page-head"><div class="container"><div class="breadcrumb"><a href="#beranda">Beranda</a> / ${parent?esc(parent)+' / ':''}<span>${esc(title)}</span></div><h1>${esc(title)}</h1>${desc?`<p>${esc(desc)}</p>`:''}</div></section>`;}
function serviceCard(s){return `<a href="#layanan/${s.id}" class="service-card ${s.icon==='film'?'cine':''}"><div class="service-icon">${icon(s.icon)}</div><span class="card-arrow">${icon('up',true)}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p></a>`;}
function home(){let sv=S.services.filter(s=>['book','landmark','users','film'].includes(s.icon)).slice(0,4);if(sv.length<4)sv=S.services.slice(0,4);const news=S.posts.filter(p=>['berita','pengumuman'].includes(p.kind)).slice(0,3);const cine=S.posts.filter(p=>p.kind==='cinebudaya');const feature=cine.find(p=>p.category==='Film')||cine[0];const s=S.settings;const title=String(s.hero_title||s.tagline).split('\n');const photo=urlSafe(s.hero_image,{image:true});return publicLayout(`<section class="hero"><div class="container"><div class="hero-grid"><div><div class="eyebrow">Dari Kalimantan Timur, untuk kebudayaan</div><h1>${esc(title[0])}<br><em>${esc(title.slice(1).join(' ')||'Menghidupkan kebudayaan.')}</em></h1><p class="hero-description">${esc(s.hero_description)}</p><div class="button-row"><a class="btn" href="#layanan">Akses layanan ${icon('arrow',true)}</a><a class="btn secondary" href="#entitas">Jelajahi kebudayaan ${icon('up',true)}</a></div><div class="hero-note">${icon('shield')} Ruang bersama untuk warisan yang terus hidup.</div></div><a class="hero-art" href="#entitas">${photo?`<img class="hero-photo" src="${esc(photo)}" alt="Sampul kebudayaan pilihan pengelola">`:abstract()}<div class="art-top"><span><i class="tiny-dot"></i>RUANG KEBUDAYAAN</span><span>01 / KALTIM</span></div><div class="art-stamp" aria-hidden="true">KALTIM</div><div class="art-caption"><div><small>Warisan · Pengetahuan · Perjumpaan</small><strong>Satu ruang,<br>banyak cerita.</strong></div><span class="circle-link">${icon('up')}</span></div></a></div><div class="hero-bottom"><p>Budaya lestari, generasi menginspirasi.</p><div class="pillar-list">${['Pelindungan','Pengembangan','Pemanfaatan','Pembinaan'].map((x,i)=>`<span class="pillar"><b>0${i+1}</b>${x}</span>`).join('')}</div></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Dekat dengan masyarakat</div><h2>Layanan kebudayaan.</h2></div><a href="#layanan" class="text-link">Lihat semua layanan ${icon('arrow',true)}</a></div><div class="services-grid services-home">${sv.map(serviceCard).join('')}</div><div class="track-strip"><div class="left">${icon('search')}<div><h3>Sudah mengajukan permohonan?</h3><p>Pantau proses dan baca tanggapan pengelola menggunakan nomor tiket serta kunci lacak.</p></div></div><a href="#lacak" class="text-link">Lacak permohonan ${icon('arrow',true)}</a></div></div></section><section class="section alt"><div class="container"><div class="section-heading"><div><div class="eyebrow">Cerita dari ruang kebudayaan</div><h2>Kabar & inspirasi.</h2></div><a href="#berita" class="text-link">Semua kabar ${icon('arrow',true)}</a></div><div class="cards-grid">${news.length?news.map(card).join(''):empty('Kabar segera hadir','Berita dan pengumuman yang diterbitkan pengelola akan muncul di sini.','book')}</div></div></section><section class="cine-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Film, cerita, dan dialog kebudayaan</div><h2>Cinebudaya<span style="color:var(--accent)">.</span></h2><p>Melihat lebih dekat. Mendengar lebih dalam. Bertemu kebudayaan melalui layar dan percakapan.</p></div><a href="#cinebudaya" class="text-link">Masuk ke Cinebudaya ${icon('up',true)}</a></div><div class="cine-feature-grid"><a class="cinema-art" href="${feature?'#konten/'+feature.id:'#cinebudaya'}">${feature&&urlSafe(feature.image,{image:true})?`<img class="hero-photo" src="${esc(urlSafe(feature.image,{image:true}))}" alt="${esc(feature.title)}" loading="lazy">`:abstract()}<span class="play-circle">${icon('play')}</span><div class="art-caption"><div><small>${feature?esc(feature.category):'Ruang audiovisual'}</small><strong>${feature?esc(feature.title):'Cerita yang menghubungkan.'}</strong></div></div></a><div class="cine-list">${['Film','Cerita','Dialog'].map((c,i)=>`<a class="cine-item" href="#cinebudaya?cat=${c}"><span class="num">0${i+1}</span><div><div class="meta">${c}</div><h3>${['Kebudayaan dalam bingkai','Ingatan yang dituturkan','Gagasan yang dipertemukan'][i]}</h3><p>${['Dokumenter dan karya audiovisual.','Tulisan, penuturan, dan pengalaman.','Percakapan dan pertukaran pengetahuan.'][i]}</p></div>${icon('up')}</a>`).join('')}</div></div><div class="cine-footer">${icon('film',true)}${cine.some(p=>p.is_demo)?'Katalog awal berisi konten contoh. Materi tayang berizin ditambahkan oleh pengelola.':'Karya dan percakapan dalam ruang Cinebudaya.'}</div></div></section><section class="section"><div class="container"><div class="join-banner">${icon('spark')}<div><h2>Mari ambil bagian<br>dalam merawat kebudayaan.</h2><p>Mulai dari sebuah cerita, sebuah gagasan, atau sebuah pertemuan.</p></div><a class="btn" href="#layanan">Temukan layanan yang tepat ${icon('arrow',true)}</a></div></div></section>`,'beranda');}
function profile(tab='tentang'){const tabs=[['tentang','Tentang Balai'],['sejarah','Sejarah'],['visi','Visi & Misi'],['struktur','Struktur Organisasi']];let key={tentang:'about',sejarah:'history',visi:'vision',struktur:'organization'}[tab]||'about';return publicLayout(pageHead('Mengenal Balai','Ruang informasi kelembagaan Balai Pelestarian Kebudayaan Kaltim.')+`<section class="page-content"><div class="container"><div class="tabs">${tabs.map(([id,label])=>`<a href="#profil/${id}" class="${tab===id?'active':''}">${label}</a>`).join('')}</div><div class="split-layout"><article class="panel prose"><h2>${tabs.find(t=>t[0]===tab)?.[1]||'Tentang Balai'}</h2>${para(S.settings[key])}</article><aside class="panel service-side"><div class="service-icon">${icon('landmark')}</div><h3>Terhubung melalui kebudayaan.</h3><p>Jelajahi dokumentasi, ajukan layanan, dan temukan ruang untuk berbagi pengetahuan.</p><a class="btn" href="#layanan">Lihat layanan ${icon('arrow',true)}</a></aside></div></div></section>`,'profil');}
function servicesPage(){return publicLayout(pageHead('Layanan Kebudayaan','Akses kebutuhan kebudayaan melalui satu pintu. Pilih layanan, baca ketentuannya, lalu ajukan permohonan.')+`<section class="page-content"><div class="container"><div class="toolbar"><div class="search-field">${icon('search')}<input id="service-search" aria-label="Cari layanan" placeholder="Cari layanan yang Anda butuhkan…" data-filter="services"></div><a class="btn secondary" href="#lacak">${icon('search',true)} Lacak permohonan</a></div><div id="services-results" class="services-grid">${S.services.map(serviceCard).join('')}</div><div class="external-links"><a class="link-box" href="https://dapobud.kemdikbud.go.id/" target="_blank" rel="noopener noreferrer">${icon('globe')}<strong>DAPOBUD</strong>${icon('external',true)}</a><a class="link-box" href="https://www.lapor.go.id/" target="_blank" rel="noopener noreferrer">${icon('message')}<strong>SP4N-LAPOR!</strong>${icon('external',true)}</a>${S.settings.wbs_url?`<a class="link-box" href="${esc(urlSafe(S.settings.wbs_url))}" target="_blank" rel="noopener noreferrer"><strong>Whistleblowing System</strong>${icon('external',true)}</a>`:'<span class="link-box muted">Whistleblowing System — tautan belum diatur</span>'}</div><p class="small-text muted">CB: Cagar Budaya · ODCB: Objek yang Diduga Cagar Budaya · OPK: Objek Pemajuan Kebudayaan. Tautan eksternal merupakan layanan pihak terkait, bukan integrasi data otomatis.</p>${S.settings.review_mode?'<div class="note mt">Jenis layanan merupakan rancangan adaptasi. Ketentuan, waktu, biaya, dan ketersediaan fasilitas harus disahkan balai sebelum peluncuran resmi.</div>':''}</div></section>`,'layanan');}
function serviceDetail(id){const s=S.services.find(s=>s.id==id);if(!s)return notFound();return publicLayout(pageHead(s.title,s.description,'Layanan')+`<section class="page-content"><div class="container split-layout"><div><div class="panel"><h2>Informasi layanan</h2><p>${esc(s.description)}</p><h3 class="mt">Persyaratan</h3><ul class="plain-list">${lines(s.requirements).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3 class="mt">Alur permohonan</h3><ol class="steps">${lines(s.procedure).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>Jangka waktu</h3><p>${esc(s.time_note)}</p><h3 class="mt">Biaya</h3><p>${esc(s.fee_note)}</p></div>${s.standard_note?`<div class="note mt">${esc(s.standard_note)}</div>`:''}</div><aside class="panel service-side"><div class="service-icon">${icon(s.icon)}</div><h3>Mulai dari sini.</h3><p>Siapkan kontak aktif, uraian kebutuhan, dan dokumen pendukung bila diperlukan.</p><a class="btn" href="#ajukan/${s.id}">Ajukan permohonan ${icon('arrow',true)}</a>${s.icon==='film'?'<a class="btn secondary" href="#cinebudaya">Jelajahi Cinebudaya</a>':''}<a class="btn secondary" href="#lacak">Lacak permohonan</a></aside></div></section>`,'layanan');}
function application(id){const s=S.services.find(s=>s.id==id);if(!s)return notFound();return publicLayout(pageHead('Ajukan Permohonan',s.title,'Layanan')+`<section class="page-content"><div class="container split-layout"><form id="request-form" class="panel" enctype="multipart/form-data"><h2>Identitas & kebutuhan</h2>${S.settings.review_mode||window.BPK_PREVIEW?'<div class="note">Mode uji. Gunakan identitas contoh, bukan data pribadi nyata. Permohonan ini belum menjadi permohonan resmi kepada balai.</div>':''}<input type="hidden" name="service_id" value="${s.id}"><div class="form-grid">${field('name','Nama lengkap','','text',{required:true,max:150})}${field('email','Email aktif','','email',{required:true,max:254})}${field('phone','Nomor telepon / WhatsApp','','tel',{max:40})}${field('institution','Instansi / komunitas','','text',{max:200})}${field('message','Jelaskan kebutuhan Anda','','textarea',{required:true,full:true,max:12000,help:'Jelaskan tujuan, lokasi, dan kebutuhan yang relevan. Minimal 15 karakter.'})}<div class="field full"><label for="request-file">Lampiran pendukung (opsional)</label><input type="file" name="file" id="request-file" accept=".pdf,.jpg,.jpeg,.png,.webp"><small>PDF, JPG, PNG, atau WebP. Maksimal 8 MB. Lampiran hanya dapat diakses pengelola berwenang.</small></div></div><div hidden aria-hidden="true"><label>Biarkan kosong <input name="website" tabindex="-1" autocomplete="off"></label></div><label class="check"><input type="checkbox" name="consent" required><span>Saya menyetujui penggunaan data untuk penanganan permohonan sesuai <a href="#privasi" target="_blank">kebijakan privasi</a>. Saya tidak menyertakan data sensitif yang tidak diperlukan.</span></label><div class="form-error"></div><div class="form-actions"><a href="#layanan/${s.id}" class="btn secondary">Kembali</a><button class="btn" type="submit">Kirim permohonan ${icon('arrow',true)}</button></div></form><aside><div class="panel"><div class="service-icon">${icon(s.icon)}</div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><h3 class="mt">Setelah pengajuan</h3><ol class="steps"><li>Simpan nomor tiket dan kunci lacak.</li><li>Pengelola memeriksa permohonan Anda.</li><li>Lihat perkembangan dan tanggapan melalui menu Lacak Permohonan.</li></ol><p class="help-text">Pemberitahuan tersedia di portal. Aplikasi ini tidak mengirim email atau pesan WhatsApp secara otomatis.</p></div></aside></div></section>`,'layanan');}
function ticketPage(){if(!lastTicket)return trackPage();return publicLayout(pageHead('Permohonan Tercatat','Simpan informasi berikut sebelum meninggalkan halaman ini.')+`<section class="page-content"><div class="container" style="max-width:760px"><div class="panel"><div class="note success">${icon('check',true)} Permohonan ${lastTicket.is_demo?'uji ':''}berhasil disimpan.</div><div class="ticket"><small>Nomor tiket</small>${esc(lastTicket.code)}</div><div class="ticket"><small>Kunci lacak rahasia</small>${esc(lastTicket.access_key)}</div><p class="small-text">Kunci lacak hanya ditampilkan pada saat pengajuan. Simpan dengan aman. Jangan membagikannya kepada orang lain.</p><div class="button-row mt"><button class="btn" data-action="save-ticket">${icon('download',true)} Simpan bukti TXT</button><button class="btn secondary" data-action="copy-ticket">${icon('copy',true)} Salin</button><a class="btn secondary" href="#lacak">Lacak permohonan</a></div></div></div></section>`,'layanan');}
function trackPage(){return publicLayout(pageHead('Lacak Permohonan','Gunakan nomor tiket dan kunci lacak yang diperoleh saat mengirim permohonan.')+`<section class="page-content"><div class="container" style="max-width:850px"><form id="track-form" class="panel"><h2>Periksa perkembangan</h2><div class="form-grid">${field('code','Nomor tiket',lastTicket?.code||'','text',{required:true,placeholder:'BPK-YYYYMMDD-XXXXXXXX'})}${field('access_key','Kunci lacak',lastTicket?.access_key||'','password',{required:true})}</div><div class="form-error"></div><button class="btn" type="submit">${icon('search',true)} Periksa status</button></form><div id="track-results" class="mt">${tracked?trackingResult(tracked):''}</div></div></section>`,'layanan');}
function trackingResult(r){return `<div class="panel"><div class="panel-title"><h2 style="margin:0">${esc(r.code)}</h2>${status(r.status)}</div><p>${esc(r.service_name)}</p>${r.is_demo?'<div class="note mt">Ini adalah permohonan uji, bukan permohonan resmi.</div>':''}<div class="timeline">${r.history.map(h=>`<div class="timeline-item"><time>${dateTime(h.at)}</time><h4>${h.type==='pemohon'?'Tanggapan pemohon':esc(h.status)}</h4><p>${esc(h.message)}</p></div>`).join('')}</div>${!['Selesai','Ditolak'].includes(r.status)?`<form id="followup-form"><h3>Kirim kelengkapan atau tanggapan</h3>${field('message','Pesan tambahan','','textarea',{required:true,max:5000})}<div class="field"><label for="followup-file">Lampiran tambahan (opsional)</label><input id="followup-file" type="file" name="file" accept=".pdf,.jpg,.jpeg,.png,.webp"><small>Maksimal 8 MB per berkas.</small></div><div class="form-error"></div><button class="btn" type="submit">Kirim tanggapan ${icon('arrow',true)}</button></form>`:''}</div>`;}
const listingInfo={berita:['Kabar & Inspirasi','Berita, pengumuman, dan cerita dari ruang kebudayaan.'],entitas:['Jelajah Kebudayaan','Dokumentasi objek, pengetahuan, dan jejak kebudayaan Kalimantan Timur.'],cinebudaya:['Cinebudaya','Film, cerita, dan dialog kebudayaan. Sebuah ruang untuk melihat, membaca, dan bertukar gagasan.'],agenda:['Agenda Budaya','Temukan jadwal kegiatan kebudayaan yang diterbitkan pengelola.'],publikasi:['Publikasi & Perpustakaan','Bahan bacaan, dokumentasi, dan pengetahuan yang dapat diakses bersama.'],ppid:['Informasi Publik — PPID','Akses informasi berkala, setiap saat, serta merta, dan layanan permohonan informasi.'],sakip:['Akuntabilitas Kinerja — SAKIP','Ruang untuk rencana strategis, perjanjian kinerja, laporan kinerja, dan dokumen pendukung.'],peraturan:['Peraturan','Dokumen peraturan dan kebijakan kebudayaan yang diterbitkan pengelola.'],galeri:['Galeri Kebudayaan','Dokumentasi visual dari kegiatan dan objek kebudayaan.']};
let listKind='berita',listCat='Semua',listSearch='';
function listPosts(kind){return S.posts.filter(p=>kind==='berita'?['berita','pengumuman'].includes(p.kind):p.kind===kind);}
function listResults(){let posts=listPosts(listKind).filter(p=>(listCat==='Semua'||p.category===listCat||LABELS[p.kind]===listCat)&&(`${p.title} ${p.excerpt} ${p.body} ${p.category} ${p.location||''}`).toLocaleLowerCase('id').includes(listSearch.toLowerCase()));if(!posts.length)return empty('Belum ada konten'+(listSearch?' yang sesuai':''),'Konten yang telah diterbitkan pengelola akan muncul di sini. Coba kategori lain atau periksa kembali nanti.',listKind==='agenda'?'calendar':'folder');const documents=['ppid','sakip','peraturan'].includes(listKind);return documents?posts.map(p=>`<div class="document-row"><div class="file-icon">${icon('file')}</div><div class="text"><div class="meta">${esc(p.category)} ${badge(p)}</div><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p></div><a class="btn secondary small" href="#konten/${p.id}">Buka ${icon('arrow',true)}</a></div>`).join(''):posts.map(card).join('');}
function listing(kind,cat){listKind=kind;listCat=cat||'Semua';listSearch='';const [title,desc]=listingInfo[kind];let cats=['Semua',...new Set(listPosts(kind).map(p=>p.category).filter(Boolean))];if(kind==='cinebudaya')cats=['Semua','Film','Cerita','Dialog'];if(kind==='ppid')cats=['Semua','Informasi Berkala','Informasi Setiap Saat','Informasi Serta Merta'];if(kind==='peraturan')cats=['Semua','Undang-undang','Peraturan Pemerintah','Peraturan Menteri'];const svc=S.services.find(s=>kind==='cinebudaya'?s.icon==='film':kind==='ppid'?s.title==='Permohonan Data dan Informasi':s.icon==='library');return publicLayout(pageHead(title,desc)+`<section class="page-content"><div class="container">${['cinebudaya','ppid','publikasi'].includes(kind)&&svc?`<div class="track-strip mb"><div class="left">${icon(kind==='cinebudaya'?'film':'book')}<div><h3>${kind==='cinebudaya'?'Ingin mengadakan pemutaran atau dialog?':kind==='ppid'?'Membutuhkan informasi tertentu?':'Butuh referensi kebudayaan?'}</h3><p>${kind==='cinebudaya'?'Ajukan pemutaran, usulan karya, atau kolaborasi Cinebudaya.':'Gunakan layanan yang tersedia untuk mengajukan kebutuhan Anda.'}</p></div></div><a class="text-link" href="#layanan/${svc.id}">Ajukan layanan ${icon('arrow',true)}</a></div>`:''}<div class="toolbar"><div class="filters" style="margin:0">${cats.map(c=>`<button class="chip ${c===listCat?'active':''}" type="button" data-action="list-category" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="search-field">${icon('search')}<input placeholder="Cari ${esc(title.toLowerCase())}…" aria-label="Cari konten" data-filter="public-posts"></div></div><div id="list-results" class="${['ppid','sakip','peraturan'].includes(kind)?'document-list':'cards-grid'}">${listResults()}</div>${kind==='peraturan'?'<div class="external-links"><a class="link-box" href="https://peraturan.bpk.go.id/" target="_blank" rel="noopener noreferrer">Database peraturan BPK RI '+icon('external',true)+'</a></div>':''}${kind==='agenda'?'<p class="content-sample-notice">Tidak ada jadwal kegiatan rekaan. Tanggal dan tempat hanya ditampilkan setelah diisi pengelola.</p>':''}</div></section>`,kind);}
function videoEmbed(v){v=urlSafe(v);if(!v)return '';let u=new URL(v,location.origin);let id='';if(u.hostname==='youtu.be')id=u.pathname.slice(1);if(['www.youtube.com','youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(u.hostname))id=u.searchParams.get('v')||u.pathname.split('/').pop();if(/^[A-Za-z0-9_-]{11}$/.test(id))return `<div class="video-wrap"><iframe src="https://www.youtube-nocookie.com/embed/${id}" title="Pemutar film kebudayaan" loading="lazy" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>`;if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(u.hostname)){let n=u.pathname.split('/').pop();if(/^\d+$/.test(n))return `<div class="video-wrap"><iframe src="https://player.vimeo.com/video/${n}" title="Pemutar film kebudayaan" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen></iframe></div>`;}if(/\.(mp4|webm)$/i.test(u.pathname))return `<div class="video-wrap"><video controls preload="metadata" src="${esc(v)}">Browser tidak mendukung pemutar video.</video></div>`;return `<a class="btn secondary mt" href="${esc(v)}" target="_blank" rel="noopener noreferrer">Buka tayangan di sumber ${icon('external',true)}</a>`;}
function article(id){const p=S.posts.find(p=>p.id==id);if(!p)return notFound();let vid=videoEmbed(p.video_url);return publicLayout(`<section class="page-content"><article class="container article"><div class="breadcrumb"><a href="#beranda">Beranda</a> / <a href="#${p.kind==='pengumuman'?'berita':p.kind}">${esc(LABELS[p.kind])}</a></div><div class="meta">${esc(p.category)} ${badge(p)}</div><h1>${esc(p.title)}</h1><p class="lead">${esc(p.excerpt)}</p><div class="meta">${p.is_demo?'Contoh untuk peninjauan':date(p.created_at)} ${p.location?' · '+esc(p.location):''} ${p.duration?' · '+esc(p.duration):''}</div>${p.kind==='agenda'&&p.event_date?`<div class="note info mt">${icon('calendar',true)} ${dateTime(p.event_date)} ${p.location?' · '+esc(p.location):''}</div>`:''}${vid||thumbnail(p)}${p.kind==='cinebudaya'&&p.category!=='Cerita'&&!vid?'<div class="note mt">Belum ada tautan tayangan pada konten ini. Pengelola dapat menambahkan tautan YouTube, Vimeo, atau MP4/WebM berizin melalui panel admin.</div>':''}<div class="prose">${para(p.body)}</div>${p.attachment&&urlSafe(p.attachment)?`<a href="${esc(urlSafe(p.attachment))}" class="btn mt" target="_blank" rel="noopener noreferrer">${icon('download',true)} Buka / unduh lampiran</a>`:''}${p.source||p.credit?`<div class="article-source">${p.credit?`Kredit dokumentasi: ${esc(p.credit)}<br>`:''}${urlSafe(p.source)?`Sumber: <a href="${esc(urlSafe(p.source))}" target="_blank" rel="noopener noreferrer">${esc(p.source)}</a>`:''}</div>`:''}<div class="button-row mt"><a class="btn secondary" href="#${p.kind==='pengumuman'?'berita':p.kind}">Kembali ke ${esc(LABELS[p.kind])}</a><button class="btn secondary" data-action="share" data-id="${p.id}">${icon('copy',true)} Salin tautan</button></div></article></section>`,p.kind);}
function contact(){const s=S.settings;return publicLayout(pageHead('Kontak & Bantuan','Mari terhubung untuk pelestarian dan pemajuan kebudayaan.')+`<section class="page-content"><div class="container split-layout"><div class="panel"><h2>Terhubung dengan balai</h2><dl><div class="kv"><dt>Alamat</dt><dd>${esc(s.address||'Belum diisi pengelola.')}</dd></div><div class="kv"><dt>Email</dt><dd>${s.email?`<a href="mailto:${esc(s.email)}">${esc(s.email)}</a>`:'Belum diisi pengelola.'}</dd></div><div class="kv"><dt>Telepon</dt><dd>${esc(s.phone||'Belum diisi pengelola.')}</dd></div><div class="kv"><dt>Jam layanan</dt><dd>${esc(s.office_hours||'Jadwal resmi akan diisi pengelola.')}</dd></div></dl><div class="button-row mt">${[['maps_url','Petunjuk arah','pin'],['instagram_url','Instagram','image'],['youtube_url','YouTube','play']].filter(([key])=>urlSafe(s[key])).map(([key,label,ic])=>`<a class="btn secondary" href="${esc(urlSafe(s[key]))}" target="_blank" rel="noopener noreferrer">${icon(ic,true)} ${label}</a>`).join('')}<a class="btn" href="#layanan">Akses layanan ${icon('arrow',true)}</a></div></div><div class="panel faq"><h2>Pertanyaan umum</h2><details open><summary>Bagaimana mengajukan permohonan?</summary><p>Pilih layanan, baca informasi dan persyaratannya, kemudian lengkapi formulir pengajuan.</p></details><details><summary>Bagaimana mengetahui perkembangan?</summary><p>Buka Lacak Permohonan. Masukkan nomor tiket dan kunci lacak yang diberikan saat pengajuan.</p></details><details><summary>Apakah lampiran saya dipublikasikan?</summary><p>Tidak. Lampiran permohonan disimpan sebagai berkas privat dan hanya dapat diakses pengelola yang berwenang.</p></details><details><summary>Apakah ada pemberitahuan melalui email?</summary><p>Versi ini menyediakan tanggapan melalui portal. Pengiriman email atau WhatsApp otomatis belum diintegrasikan.</p></details><details><summary>Apa yang tersedia di Cinebudaya?</summary><p>Film, cerita tertulis, dan dokumentasi dialog kebudayaan. Karya dan rekaman dipublikasikan oleh pengelola setelah hak tayangnya dipastikan.</p></details></div></div></section>`);}
function privacy(){return publicLayout(pageHead('Kebijakan Privasi','Informasi penggunaan data pada portal layanan.')+`<section class="page-content"><div class="container article"><div class="panel prose">${para(S.settings.privacy_text)}${S.settings.review_mode||window.BPK_PREVIEW?'<div class="note">Mode peninjauan bukan kanal resmi pengumpulan data. Gunakan data uji, bukan data pribadi nyata.</div>':''}</div></div></section>`);}
function sources(){return publicLayout(pageHead('Sumber & Kredit','Asal referensi, aset, dan catatan penerapan portal.')+`<section class="page-content"><div class="container article"><div class="panel"><div class="license-item"><h3>Referensi struktur dan layanan</h3><p>Struktur menu merujuk Budaya Jatim, termasuk portal Unit Layanan Terpadu. Layanan identifikasi lokasi Trowulan diadaptasi menjadi kawasan cagar budaya Kaltim. Cinebudaya ditambahkan sesuai rancangan pengguna. Adaptasi tidak otomatis menjadi standar layanan resmi Kaltim.</p><a href="https://budayajatim.com/layanan/" target="_blank" rel="noopener noreferrer">budayajatim.com/layanan/</a><br><a href="https://layanan.budayajatim.com/ult/layanan" target="_blank" rel="noopener noreferrer">Portal ULT — daftar layanan</a></div><div class="license-item"><h3>Logo Kementerian Kebudayaan</h3><p>Logo karya Kementerian Kebudayaan Republik Indonesia, melalui Wikimedia Commons. Warna dan bentuk logo tidak diganti mengikuti tema. Aset dimuat dari sumber daring bila belum disimpan lokal. Halaman sumber mencantumkan status PD Indonesian Government. Penggunaannya dalam rancangan ini bukan pernyataan bahwa situs telah disahkan kementerian.</p><a href="https://commons.wikimedia.org/wiki/File:Logo_Kementerian_Kebudayaan_Republik_Indonesia_(2024).svg" target="_blank" rel="noopener noreferrer">Sumber dan keterangan logo</a></div><div class="license-item"><h3>Visual dan konten awal</h3><p>Ornamen geometris adalah dekorasi antarmuka, bukan representasi motif adat tertentu. Tidak ada foto lapangan, peristiwa, pejabat, jadwal, atau statistik layanan rekaan. Konten contoh diberi label dan dapat disunting atau dihapus pengelola. Film tidak disertakan tanpa materi dan izin tayang.</p></div><div class="license-item"><h3>Pratinjau dan aplikasi server</h3><p>HTML pratinjau menggunakan penyimpanan browser, sehingga login dan datanya hanya simulasi. Jangan menggunakannya sebagai sistem produksi. Paket server menggunakan FastAPI dan SQLite dengan sesi sisi server, kontrol akses, validasi berkas, serta pencatatan aktivitas. Data server tersimpan pada folder data dan tidak bercampur dengan HTML pratinjau.</p></div><div class="license-item"><h3>Sebelum peluncuran resmi</h3><p>Ganti kata sandi awal, lengkapi identitas dan kebijakan data, sahkan standar layanan, periksa hak penggunaan materi, pasang HTTPS, dan lakukan pengujian keamanan pada lingkungan hosting. Instalasi ini belum dipublikasikan pada domain.</p></div><p class="small-text">Referensi ditinjau pada 18 September 2026.</p></div></div></section>`);}
function loginPage(){return publicLayout(`<section class="page-content"><div class="container" style="max-width:1100px"><div class="login-layout"><div class="login-art">${abstract()}<div><div class="eyebrow" style="color:var(--accent)">Ruang pengelola</div><h2>Merawat cerita.<br>Mengelola pengetahuan.</h2><p>Satu panel untuk konten, layanan, dan identitas digital kebudayaan Kaltim.</p></div><p class="flyout-note">Akses hanya untuk pengelola yang berwenang.</p></div><form id="login-form" class="login-form"><h1>Selamat datang.</h1><p>Masuk ke panel admin Balai Pelestarian Kebudayaan Kaltim.</p>${field('username','Username','','text',{required:true,autocomplete:'username',max:64,placeholder:'Masukkan username'})}${passwordField('password','Kata sandi')}<div class="form-error"></div><button class="btn" type="submit">Masuk ke panel ${icon('arrow',true)}</button><p class="login-footer">${window.BPK_PREVIEW?'Mode pratinjau — login hanya berlaku di browser ini.':'Sesi pengelola berakhir setelah 8 jam.'}</p></form></div></div></section>`);}
function notFound(){return publicLayout(pageHead('Halaman tidak ditemukan')+`<section class="page-content"><div class="container">${empty('Halaman belum tersedia','Konten mungkin belum diterbitkan atau telah dihapus pengelola.','search','<a href="#beranda" class="btn">Kembali ke beranda</a>')}</div></section>`);}
const adminNav=[['dashboard','Dasbor','grid',['superadmin','admin','editor','operator']],['konten','Konten & Cinebudaya','edit',['superadmin','admin','editor']],['layanan','Jenis Layanan','landmark',['superadmin','admin']],['media','Gambar & PDF','image',['superadmin','admin','editor']],['permohonan','Permohonan','folder',['superadmin','admin','operator']],['identitas','Identitas Website','settings',['superadmin','admin']],['tampilan','Warna & Tampilan','palette',['superadmin','admin']],['pengguna','Pengguna & Admin','users',['superadmin']],['ekspor','Ekspor Data','download',['superadmin','admin','editor','operator']],['audit','Riwayat Aktivitas','history',['superadmin','admin']],['akun','Akun Saya','user',['superadmin','admin','editor','operator']]];
function adminLayout(content,section){const u=S.user;return `<div class="admin-shell"><aside class="sidebar"><div class="admin-brand"><div class="badge-square">B / K</div><div><h2>Balai Pelestarian<br>Kebudayaan Kaltim</h2><small>Panel pengelola</small></div></div><button class="admin-menu mobile-only" data-action="toggle-admin" aria-label="Buka menu pengelola">${icon('menu')}</button><div class="side-nav-group"><div class="sidebar-label">Ruang kerja</div><nav class="side-links" aria-label="Panel admin">${adminNav.filter(n=>n[3].includes(u.role)).map(([key,title,ic])=>`<a href="#admin/${key}" class="${section===key?'active':''}">${icon(ic)}${title}</a>`).join('')}</nav></div><div class="sidebar-bottom"><a href="#beranda">${icon('globe')}Lihat website</a><button data-action="logout">${icon('logout')}Keluar akun</button></div></aside><div class="admin-main"><header class="admin-top"><p>${window.BPK_PREVIEW?'PRATINJAU LOKAL · Data tersimpan hanya di browser ini.':'Pengelolaan informasi dan layanan kebudayaan'}</p><span class="mobile-label">Panel Admin</span><a class="user-badge" href="#admin/akun"><span class="avatar">${esc(u.display_name.charAt(0).toUpperCase())}</span><span><strong>${esc(u.display_name)}</strong><small>${esc(ROLE_LABELS[u.role])}</small></span></a></header><main id="main" class="admin-content" tabindex="-1">${u.force_change&&section!=='akun'?'<div class="note">Kata sandi awal masih digunakan. <a href="#admin/akun"><b>Ganti melalui Akun Saya</b></a> sebelum digunakan secara publik.</div>':''}${content}</main></div></div>`;}
function adminTitle(title,desc,button=''){return `<div class="admin-title"><div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${button}</div>`;}
function requestTable(rows){if(!rows.length)return empty('Belum ada permohonan','Permohonan yang dikirim melalui formulir website akan muncul di sini.','folder');return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Nomor / pemohon</th><th>Layanan</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="title">${esc(r.code)}<span class="sub">${esc(r.name)} · ${date(r.created_at,true)}</span></td><td>${esc(r.service_name)}</td><td>${status(r.status)}</td><td>${actionButton('request-open','Lihat dan tangani permohonan','eye',r.id)}</td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(d){return adminTitle('Selamat datang, '+S.user.display_name+'.','Ringkasan konten dan permohonan pada portal kebudayaan.')+`<div class="stat-grid">${[['Konten terbit',d.published,'file'],['Draf konten',d.draft,'edit'],['Permohonan masuk',d.requests??'—','folder'],['Berkas publik',d.media,'image']].map(([l,v,ic])=>`<div class="stat-card"><small>${l}</small><strong>${v}</strong>${icon(ic)}</div>`).join('')}</div><div class="admin-grid"><section><div class="panel-title"><h3>${S.user.role==='editor'?'Ruang editorial':'Permohonan terbaru'}</h3>${S.user.role!=='editor'?'<a class="text-link" href="#admin/permohonan">Lihat semua</a>':''}</div>${S.user.role==='editor'?`<div class="panel"><h2>Siapkan cerita berikutnya.</h2><p>Buat artikel, perbarui katalog Cinebudaya, dan unggah dokumen yang sudah ditinjau.</p><a class="btn mt" href="#admin/konten">Kelola konten</a></div>`:requestTable(d.recent_requests)}</section><aside class="panel"><h3>Akses cepat</h3><div class="quick-admin">${S.user.role!=='operator'?'<a href="#admin/konten">'+icon('edit')+'Kelola konten dan Cinebudaya '+icon('arrow',true)+'</a>':''}${['admin','superadmin'].includes(S.user.role)?'<a href="#admin/identitas">'+icon('settings')+'Lengkapi identitas '+icon('arrow',true)+'</a>':''}<a href="#admin/ekspor">${icon('download')}Ekspor data ${icon('arrow',true)}</a><a href="#beranda">${icon('globe')}Lihat website ${icon('up',true)}</a></div><p class="help-text mt">${S.settings.review_mode?'Website berada dalam mode peninjauan. Tinjau konten contoh dan pengaturan sebelum peluncuran.':'Website telah dikeluarkan dari mode peninjauan oleh pengelola.'}</p></aside></div>`;}
let adminKind='Semua',adminSearch='',adminPage=1;
function adminPostRows(){let all=S.adminPosts.filter(p=>(adminKind==='Semua'||p.kind===adminKind)&&`${p.title} ${p.category}`.toLowerCase().includes(adminSearch.toLowerCase()));const pageSize=12;const pages=Math.max(1,Math.ceil(all.length/pageSize));adminPage=Math.min(adminPage,pages);let rows=all.slice((adminPage-1)*pageSize,adminPage*pageSize);return (!rows.length?empty('Belum ada konten','Tambahkan konten baru atau ganti pencarian.','file'):`<div class="table-wrap"><table class="data-table"><thead><tr><th>Judul konten</th><th>Jenis</th><th>Status</th><th>Diperbarui</th><th>Aksi</th></tr></thead><tbody>${rows.map(p=>`<tr><td class="title">${esc(p.title)}<span class="sub">${esc(p.category)} ${badge(p)}</span></td><td>${esc(LABELS[p.kind])}</td><td>${status(p.status)}</td><td>${date(p.updated_at,true)}</td><td><div class="row-actions">${actionButton('post-edit','Sunting konten','edit',p.id)}${p.status==='published'?`<a class="icon-btn" href="#konten/${p.id}" title="Lihat konten" aria-label="Lihat konten">${icon('eye')}</a>`:''}${actionButton('post-delete','Hapus konten','trash',p.id)}</div></td></tr>`).join('')}</tbody></table></div>`)+`<div class="pager"><span>${all.length} konten · Halaman ${adminPage} dari ${pages}</span><div class="buttons"><button class="btn secondary small" data-action="posts-prev" ${adminPage<=1?'disabled':''}>Sebelumnya</button><button class="btn secondary small" data-action="posts-next" ${adminPage>=pages?'disabled':''}>Berikutnya</button></div></div>`;}
function postsAdmin(){adminKind='Semua';adminSearch='';adminPage=1;return adminTitle('Konten & Cinebudaya','Kelola artikel, tayangan, dokumen publik, agenda, dan galeri.',`<button class="btn" data-action="post-new">${icon('plus',true)} Tambah konten</button>`)+`<div class="admin-toolbar"><div class="search-field">${icon('search')}<input aria-label="Cari konten admin" placeholder="Cari judul atau kategori…" data-filter="admin-posts"></div><select id="admin-kind" aria-label="Filter jenis konten"><option value="Semua">Semua jenis</option>${Object.entries(LABELS).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><span class="count">Draf tidak ditampilkan kepada pengunjung.</span></div><div id="admin-post-results">${adminPostRows()}</div>`;}
function attachmentField(name,label,value,accept){return `<div class="field full"><label for="f-${name}">${label}</label><div class="field-link"><input id="f-${name}" name="${name}" value="${esc(value||'')}" placeholder="Tempel tautan atau unggah berkas"><button class="btn secondary small" type="button" data-action="media-picker" data-target="f-${name}" data-kind="${['image','logo_url','hero_image'].includes(name)?'image':'all'}">Pilih dari pustaka</button></div><div class="inline-upload"><input type="file" data-upload-target="f-${name}" accept="${accept}" aria-label="Unggah ${label}"><small>Unggah maks. 8 MB.</small></div></div>`;}
function editPost(id){let p=S.adminPosts.find(p=>p.id==id)||{kind:'berita',status:'draft',is_demo:false};showModal(id?'Sunting konten':'Tambah konten',`<form id="post-form" data-id="${id||''}"><div class="form-grid">${select('kind','Jenis konten',p.kind,Object.entries(LABELS),{required:true})}${select('status','Status publikasi',p.status,[['draft','Draf — hanya pengelola'],['published','Terbit — tampil di website']])}${field('title','Judul',p.title||'','text',{required:true,full:true,max:200})}${field('category','Kategori',p.category||'','text',{max:100,help:'Cinebudaya: Film, Cerita, atau Dialog. PPID: Informasi Berkala, Informasi Setiap Saat, Informasi Serta Merta.'})}${field('location','Lokasi',p.location||'','text',{max:200})}${field('excerpt','Ringkasan',p.excerpt||'','textarea',{full:true,max:500,rows:2})}${field('body','Isi konten',p.body||'','textarea',{full:true,long:true,help:'Gunakan teks biasa. Pisahkan paragraf dengan baris kosong; kode HTML tidak dijalankan.'})}${attachmentField('image','Gambar sampul',p.image,'.jpg,.jpeg,.png,.webp')}${attachmentField('attachment','Lampiran PDF / gambar',p.attachment,'.pdf,.jpg,.jpeg,.png,.webp')}${field('video_url','Tautan tayangan',p.video_url||'','text',{full:true,help:'YouTube, Vimeo, atau URL MP4/WebM berizin. Tidak menerima kode embed HTML.'})}${field('duration','Durasi',p.duration||'','text',{help:'Opsional, misalnya 12 menit.'})}${field('event_date','Tanggal agenda',p.event_date||'','datetime-local',{help:'Isi hanya untuk kegiatan dengan jadwal yang sudah terkonfirmasi.'})}${field('source','Tautan sumber',p.source||'','text',{full:true})}${field('credit','Kredit foto / karya & hak tayang',p.credit||'','text',{full:true,max:500})}</div>${check('is_demo','Tandai sebagai konten contoh, bukan publikasi resmi.',p.is_demo)}<div class="form-error"></div><div class="form-actions"><button class="btn secondary" type="button" data-action="close-modal">Batal</button><button class="btn" type="submit">${icon('check',true)} Simpan konten</button></div></form>`);}
function servicesAdmin(){return adminTitle('Jenis Layanan','Sesuaikan informasi, persyaratan, alur, dan ketersediaan layanan.',`<button class="btn" data-action="service-new">${icon('plus',true)} Tambah layanan</button>`)+`<div class="table-wrap"><table class="data-table"><thead><tr><th>Urutan</th><th>Nama layanan</th><th>Ketersediaan</th><th>Aksi</th></tr></thead><tbody>${S.adminServices.map(s=>`<tr><td>${s.sort_order}</td><td class="title">${esc(s.title)}<span class="sub">${esc(s.description)}</span></td><td>${status(s.active?'active':'inactive')}</td><td><div class="row-actions">${actionButton('service-edit','Sunting layanan','edit',s.id)}${actionButton('service-delete','Hapus layanan','trash',s.id)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function editService(id){let s=S.adminServices.find(x=>x.id==id)||{active:true,sort_order:S.adminServices.length+1,icon:'landmark'};showModal(id?'Sunting layanan':'Tambah layanan',`<form id="service-form" data-id="${id||''}"><div class="form-grid">${field('title','Nama layanan',s.title||'','text',{required:true,full:true,max:200})}${field('description','Uraian singkat',s.description||'','textarea',{full:true,max:1500})}${select('icon','Ikon layanan',s.icon,[['landmark','Warisan / kajian'],['shield','Pelindungan'],['leaf','Pemanfaatan'],['book','Edukasi'],['users','Narasumber'],['briefcase','Magang'],['map','Lokasi'],['search','Temuan'],['heart','Advokasi'],['library','Perpustakaan'],['message','Pengaduan'],['building','Ruang'],['file','Informasi'],['film','Cinebudaya']])}${field('sort_order','Urutan tampilan',s.sort_order,'number')}${field('requirements','Persyaratan',s.requirements||'','textarea',{full:true,max:5000,help:'Satu persyaratan per baris.'})}${field('procedure','Alur permohonan',s.procedure||'','textarea',{full:true,max:5000,help:'Satu langkah per baris; nomor dibuat otomatis.'})}${field('time_note','Jangka waktu',s.time_note||'','textarea',{max:1000})}${field('fee_note','Biaya',s.fee_note||'','textarea',{max:1000})}${field('standard_note','Catatan standar layanan',s.standard_note||'','textarea',{full:true,max:2000})}${field('source','Tautan sumber / standar',s.source||'','text',{full:true})}</div>${check('active','Layanan aktif dan tampil kepada pengunjung.',s.active)}<div class="form-error"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-modal">Batal</button><button class="btn" type="submit">Simpan layanan</button></div></form>`);}
function mediaAdmin(){return adminTitle('Pustaka Gambar & PDF','Berkas di pustaka ini bersifat publik. Lampiran permohonan tetap privat.')+`<div class="upload-zone">${icon('upload')}<div><h3>Unggah dokumentasi atau publikasi</h3><p>JPG, PNG, WebP, PDF · Maksimal 8 MB per berkas.</p></div><input type="file" id="media-upload" multiple accept=".pdf,.jpg,.jpeg,.png,.webp" aria-label="Unggah berkas ke pustaka publik"></div>${S.media.length?`<div class="media-grid">${S.media.map(m=>`<article class="media-item"><div class="preview">${m.mime.startsWith('image/')?`<img src="${esc(urlSafe(m.url,{image:true}))}" alt="${esc(m.name)}" loading="lazy">`:icon('file')}</div><div class="media-body"><h3>${esc(m.name)}</h3><p>${bytes(m.size)} · ${date(m.created_at,true)}</p><div class="media-actions"><button class="btn secondary small" data-action="media-copy" data-id="${m.id}">${icon('copy',true)} Tautan</button><a class="btn secondary small" href="${esc(urlSafe(m.url))}" target="_blank" rel="noopener noreferrer">Buka</a>${actionButton('media-delete','Hapus berkas','trash',m.id)}</div></div></article>`).join('')}</div>`:empty('Pustaka masih kosong','Unggah gambar atau PDF untuk digunakan dalam konten website.','image')}`;}
let requestFilter='Semua',requestSearch='';
function filteredRequests(){return requestTable(S.requests.filter(r=>(requestFilter==='Semua'||r.status===requestFilter)&&`${r.code} ${r.name} ${r.service_name}`.toLowerCase().includes(requestSearch.toLowerCase())));}
function requestsAdmin(){requestFilter='Semua';requestSearch='';return adminTitle('Permohonan Layanan','Periksa berkas, tentukan petugas, dan sampaikan tindak lanjut.',`<a href="#admin/ekspor" class="btn secondary">${icon('download',true)} Ekspor</a>`)+`<div class="admin-toolbar"><div class="search-field">${icon('search')}<input aria-label="Cari permohonan" placeholder="Cari tiket, nama, atau layanan…" data-filter="requests"></div><select id="request-status-filter" aria-label="Filter status"><option>Semua</option>${STATUSES.map(s=>`<option>${s}</option>`).join('')}</select><span class="count">${S.requests.length} permohonan</span></div><div id="request-results">${filteredRequests()}</div>`;}
async function requestModal(id){const [r,staff]=await Promise.all([api('/admin/requests/'+id),api('/admin/assignees')]);showModal('Tindak lanjut permohonan',`<div class="meta">${esc(r.code)} ${status(r.status)}</div><dl><div class="kv"><dt>Nama</dt><dd>${esc(r.name)}</dd></div><div class="kv"><dt>Layanan</dt><dd>${esc(r.service_name)}</dd></div><div class="kv"><dt>Email</dt><dd>${esc(r.email)}</dd></div><div class="kv"><dt>Telepon</dt><dd>${esc(r.phone||'—')}</dd></div><div class="kv"><dt>Instansi</dt><dd>${esc(r.institution||'—')}</dd></div></dl><div class="request-message">${esc(r.message)}</div>${r.attachments.length?`<h3>Lampiran privat</h3><div class="button-row mb">${r.attachments.map(m=>`<a class="btn secondary small" href="${esc(urlSafe(m.url))}" target="_blank" rel="noopener noreferrer">${icon('download',true)} ${esc(m.name)}</a>`).join('')}</div>`:''}<details class="mb"><summary>Riwayat permohonan (${r.history.length})</summary><div class="timeline">${r.history.map(h=>`<div class="timeline-item"><time>${dateTime(h.at)}</time><h4>${h.type==='pemohon'?'Pemohon':esc(h.status)}</h4><p>${esc(h.message)}</p></div>`).join('')}</div></details><form id="request-admin-form" data-id="${id}"><div class="form-grid">${select('status','Status permohonan',r.status,STATUSES)}${select('assigned_to','Petugas',r.assigned_to||'',[['','Belum ditugaskan'],...staff.map(s=>[s.id,s.display_name])])}${field('public_reply','Tanggapan untuk pemohon',r.public_reply||'','textarea',{full:true,max:5000,help:'Teks ini terlihat oleh pemohon melalui nomor tiket dan kunci lacak.'})}${field('internal_note','Catatan internal',r.internal_note||'','textarea',{full:true,max:5000,help:'Tidak ditampilkan kepada pemohon.'})}</div><div class="form-error"></div><div class="form-actions">${['superadmin','admin'].includes(S.user.role)?`<button class="btn danger small" type="button" data-action="request-delete" data-id="${id}">Hapus data</button>`:''}<button class="btn secondary" type="button" data-action="close-modal">Tutup</button><button class="btn" type="submit">Simpan tindak lanjut</button></div></form>`);}
function identityAdmin(){const s=S.settings;return adminTitle('Identitas Website','Perbarui identitas, profil, kontak, dan kebijakan data pada website.')+`<form id="identity-form" class="panel"><div class="form-grid">${field('site_name','Nama website',s.site_name,'text',{required:true,full:true})}${field('tagline','Tagline',s.tagline,'text',{full:true})}${field('hero_title','Judul halaman depan',s.hero_title,'textarea',{full:true,help:'Pisahkan dua bagian judul dengan satu baris baru.'})}${field('hero_description','Deskripsi halaman depan',s.hero_description,'textarea',{full:true})}${attachmentField('logo_url','Logo utama Kementerian Kebudayaan',s.logo_url,'.jpg,.jpeg,.png,.webp')}${attachmentField('hero_image','Gambar sampul halaman depan',s.hero_image,'.jpg,.jpeg,.png,.webp')}${field('about','Tentang Balai',s.about,'textarea',{full:true,long:true,max:10000})}${field('history','Sejarah kelembagaan',s.history,'textarea',{full:true,max:10000})}${field('vision','Visi dan misi',s.vision,'textarea',{full:true,max:10000})}${field('organization','Struktur organisasi',s.organization,'textarea',{full:true,max:10000})}${field('address','Alamat kantor',s.address,'textarea',{full:true})}${field('email','Email resmi',s.email,'email')}${field('phone','Telepon resmi',s.phone,'text')}${field('office_hours','Jam layanan',s.office_hours,'text',{full:true})}${field('maps_url','Tautan lokasi / peta',s.maps_url,'text',{full:true})}${field('instagram_url','Tautan Instagram',s.instagram_url)}${field('youtube_url','Tautan YouTube',s.youtube_url)}${field('wbs_url','Tautan Whistleblowing System',s.wbs_url,'text',{full:true})}${field('privacy_text','Kebijakan privasi dan retensi data',s.privacy_text,'textarea',{full:true,long:true,max:10000})}</div>${check('review_mode','Aktifkan mode peninjauan: tampilkan pemberitahuan bahwa layanan belum resmi.',s.review_mode)}<div class="note">Sebelum menonaktifkan mode peninjauan, ganti kata sandi awal dan lengkapi kontak resmi. Konten yang masih ditandai sebagai contoh tetap memiliki labelnya.</div><div class="form-error"></div><div class="form-actions"><button type="submit" class="btn">${icon('check',true)} Simpan identitas</button></div></form>`;}
const palettes=[['Coklat Warisan','#5B3629','#C69A58','#FAF7F2'],['Kopi & Krem','#49372B','#BA9361','#F7F1E7'],['Tanah & Tembaga','#724737','#D1A275','#FCF6EF']];
function themeAdmin(){return adminTitle('Warna & Tampilan','Terapkan kombinasi warna sendiri tanpa mengubah warna logo kementerian.')+`<div class="panel"><h2>Palet pilihan</h2><div class="swatch-grid">${palettes.map((p,i)=>`<button class="swatch" type="button" data-action="palette" data-id="${i}"><span class="swatch-colors">${p.slice(1).map(c=>`<span style="background:${c}"></span>`).join('')}</span><strong>${p[0]}</strong></button>`).join('')}</div><form id="theme-form"><div class="form-grid">${field('primary_color','Warna utama',S.settings.primary_color,'color')}${field('accent_color','Warna aksen',S.settings.accent_color,'color')}${field('background_color','Latar website',S.settings.background_color,'color')}</div><div class="theme-preview"><div class="theme-preview-top">Balai Pelestarian Kebudayaan Kaltim</div><div class="theme-preview-body"><h2>Merawat warisan.</h2><p>Pratinjau warna utama, latar, dan aksen pada website.</p><span class="btn gold">Akses layanan ${icon('arrow',true)}</span></div></div><div class="form-error"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="theme-reset">Batalkan pratinjau</button><button type="submit" class="btn">Simpan tampilan</button></div></form></div>`;}
function usersAdmin(){return adminTitle('Pengguna & Admin','Kelola akun pengelola, peran, dan status akses.',`<button class="btn" data-action="user-new">${icon('plus',true)} Tambah pengguna</button>`)+`<div class="note info">Superadmin: seluruh akses. Admin: konten, layanan, permohonan, dan pengaturan. Editor: konten dan berkas publik. Petugas: penanganan permohonan. Hanya superadmin yang dapat mengelola pengguna.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Nama / username</th><th>Peran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${S.users.map(u=>`<tr><td class="title">${esc(u.display_name)}<span class="sub">${esc(u.username)} ${u.id===S.user.id?'· Akun Anda':''}</span></td><td>${esc(ROLE_LABELS[u.role])}</td><td>${status(u.active?'active':'inactive')}</td><td><div class="row-actions">${actionButton('user-edit','Sunting pengguna','edit',u.id)}${u.id!==S.user.id?actionButton('user-delete','Hapus pengguna','trash',u.id):''}</div></td></tr>`).join('')}</tbody></table></div>`;}
function editUser(id){const u=S.users.find(x=>x.id==id)||{role:'editor',active:true};showModal(id?'Sunting pengguna':'Tambah pengguna',`<form id="user-form" data-id="${id||''}"><div class="form-grid">${field('username','Username',u.username||'','text',{required:true,readonly:!!id,max:64,autocomplete:'off'})}${field('display_name','Nama tampilan',u.display_name||'','text',{required:true,max:100})}${select('role','Peran',u.role,Object.entries(ROLE_LABELS),{full:true})}${field('password',id?'Kata sandi baru (kosongkan bila tidak diganti)':'Kata sandi awal','','password',{required:!id,full:true,max:128,autocomplete:'new-password',help:'Minimal 10 karakter dengan huruf, angka, dan simbol. Jangan memakai kembali kata sandi awal situs.'})}</div>${check('active','Akun aktif dan dapat login.',u.active)}<div class="form-error"></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-modal">Batal</button><button type="submit" class="btn">Simpan pengguna</button></div></form>`);}
function exportsAdmin(){const allowed={superadmin:['requests','posts','services','users','audit','all'],admin:['requests','posts','services','audit'],editor:['posts'],operator:['requests']}[S.user.role];const names={requests:['Permohonan layanan','Data pemohon, layanan, status, dan tindak lanjut.','folder'],posts:['Seluruh konten','Artikel, Cinebudaya, dokumen, agenda, dan galeri.','file'],services:['Jenis layanan','Informasi, ketentuan, dan ketersediaan layanan.','landmark'],users:['Daftar pengguna','Identitas dan peran. Tanpa hash kata sandi atau sesi.','users'],audit:['Riwayat aktivitas','Catatan tindakan pengelola pada aplikasi.','history'],all:['Paket data & berkas','Semua dataset dan lampiran dalam satu ZIP. Khusus superadmin.','download']};return adminTitle('Ekspor Data','Unduh data untuk rekap, pengolahan, dan dokumentasi.')+`<div class="note">Ekspor permohonan mengandung data pribadi. Simpan hanya pada tempat yang berwenang dan jangan membagikannya secara terbuka. Ekspor data tidak menyertakan kata sandi, sesi login, atau kunci lacak.</div><div class="export-grid">${allowed.map(k=>`<article class="export-card">${icon(names[k][2])}<h3>${names[k][0]}</h3><p>${names[k][1]}</p><div class="button-row">${(k==='all'?['zip']:['csv','json']).map(f=>`<button class="btn secondary small" data-action="export" data-dataset="${k}" data-format="${f}">${icon('download',true)} ${f.toUpperCase()}</button>`).join('')}</div></article>`).join('')}</div>${window.BPK_PREVIEW?'<p class="help-text mt">Dalam pratinjau lokal, paket lengkap diekspor sebagai JSON. ZIP beserta berkas tersedia pada aplikasi server.</p>':''}`;}
function auditAdmin(){return adminTitle('Riwayat Aktivitas','500 tindakan terakhir. Kata sandi dan isi dokumen pribadi tidak dicatat.')+`<div class="panel">${S.audit.length?S.audit.map(a=>`<div class="audit-row">${icon('history')}<div><strong>${esc(a.actor)} · ${esc(a.action)}</strong><p>${esc(a.entity)}</p></div><time>${dateTime(a.created_at)}</time></div>`).join(''):empty('Belum ada aktivitas','Tindakan pengelola akan dicatat setelah dilakukan.','history')}</div>`;}
function accountAdmin(){return adminTitle('Akun Saya','Ubah kata sandi untuk menjaga akses pengelolaan website.')+`<div class="split-layout"><form id="password-form" class="panel"><h2>Ganti kata sandi</h2>${passwordField('old_password','Kata sandi saat ini')}${passwordField('new_password','Kata sandi baru','new-password')}${passwordField('confirm_password','Ulangi kata sandi baru','new-password')}<p class="help-text">Minimal 10 karakter, menggunakan kombinasi huruf, angka, dan simbol. Sesi lama pada perangkat lain akan dikeluarkan.</p><div class="form-error"></div><div class="form-actions"><button type="submit" class="btn">${icon('lock',true)} Ganti kata sandi</button></div></form><div class="panel" style="align-self:start"><h3>${esc(S.user.display_name)}</h3><p>${esc(S.user.username)}</p><div class="meta mt">${esc(ROLE_LABELS[S.user.role])}</div>${window.BPK_PREVIEW?'<div class="note mt">Akun pratinjau tersimpan di browser, bukan akun pada aplikasi server. Jangan gunakan kata sandi pribadi untuk simulasi ini.</div><button class="btn secondary small" data-action="reset-preview">Hapus data pratinjau</button>':''}</div></div>`;}
async function render(){const n=++routeVersion;const raw=(location.hash.slice(1)||'beranda');const [path,qs]=raw.split('?');const seg=path.split('/');const root=seg[0];const query=new URLSearchParams(qs||'');let html='';if($('#modal').open)closeModal();applyTheme();try{if(root==='admin'){if(!S.user){go('login');return;}let section=seg[1]||'dashboard';let nav=adminNav.find(x=>x[0]===section);if(!nav||!nav[3].includes(S.user.role)){html=adminLayout(empty('Akses dibatasi','Akun ini tidak memiliki izin untuk membuka halaman tersebut.','lock'),'dashboard');}else{let content='';switch(section){case'dashboard':content=dashboard(await api('/admin/overview'));break;case'konten':S.adminPosts=await api('/admin/posts');content=postsAdmin();break;case'layanan':S.adminServices=await api('/admin/services');content=servicesAdmin();break;case'media':S.media=await api('/admin/media');content=mediaAdmin();break;case'permohonan':S.requests=await api('/admin/requests');content=requestsAdmin();break;case'identitas':content=identityAdmin();break;case'tampilan':content=themeAdmin();break;case'pengguna':S.users=await api('/admin/users');content=usersAdmin();break;case'ekspor':content=exportsAdmin();break;case'audit':S.audit=await api('/admin/audit');content=auditAdmin();break;case'akun':content=accountAdmin();break;}html=adminLayout(content,section);}}else{switch(root){case'beranda':html=home();break;case'profil':html=profile(seg[1]||'tentang');break;case'layanan':html=seg[1]?serviceDetail(seg[1]):servicesPage();break;case'ajukan':html=application(seg[1]);break;case'tiket':html=ticketPage();break;case'lacak':html=trackPage();break;case'login':html=S.user?null:loginPage();if(S.user){go('admin/dashboard');return;}break;case'konten':html=article(seg[1]);break;case'kontak':html=contact();break;case'privasi':html=privacy();break;case'sumber':html=sources();break;default:html=listingInfo[root]?listing(root,query.get('cat')):notFound();}}
 if(n!==routeVersion)return;$('#app').innerHTML=html;window.scrollTo({top:0,behavior:'instant'});document.title=(root==='admin'?'Panel Admin · ':'')+S.settings.site_name;
 }catch(e){if(n!==routeVersion)return;$('#app').innerHTML=publicLayout(pageHead('Halaman belum dapat dibuka')+`<section class="page-content"><div class="container">${empty('Terjadi kendala',e.message,'info','<button class="btn" data-action="retry">Coba lagi</button>')}</div></section>`);}}
async function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Berhasil disalin.');}catch{showModal('Salin informasi',`<textarea class="full-width" rows="5" readonly>${esc(s)}</textarea><p class="small-text muted mt">Pilih teks, lalu tekan Ctrl+C.</p>`);}}
function ticketText(){return `BUKTI PERMOHONAN${lastTicket.is_demo?' UJI':''}\nBalai Pelestarian Kebudayaan Kaltim\nNomor tiket: ${lastTicket.code}\nKunci lacak: ${lastTicket.access_key}\nStatus awal: ${lastTicket.status}\n\nSimpan kunci lacak secara rahasia.\n${window.BPK_PREVIEW?'Pratinjau lokal; bukan permohonan resmi.':''}`;}
async function saveAndRefresh(msg){closeModal();await refresh();await render();toast(msg);}
async function remove(path,question,msg){if(!window.confirm(question))return;await api(path,{method:'DELETE'});await saveAndRefresh(msg);}
async function handleAction(b){const a=b.dataset.action,id=b.dataset.id;
 switch(a){case'toggle-nav':{let nav=$('.nav-links');nav.classList.toggle('open');b.setAttribute('aria-expanded',nav.classList.contains('open'));break;}case'toggle-admin':$('.sidebar').classList.toggle('expanded');break;case'close-modal':closeModal();break;case'eye':{let input=document.getElementById(b.dataset.target);input.type=input.type==='password'?'text':'password';b.innerHTML=icon(input.type==='password'?'eye':'eyeoff');b.setAttribute('aria-label',input.type==='password'?'Tampilkan kata sandi':'Sembunyikan kata sandi');break;}case'logout':{setSession(await api('/logout',{method:'POST'}));go('beranda');toast('Anda telah keluar.');break;}case'retry':await render();break;case'post-new':editPost();break;case'post-edit':editPost(id);break;case'post-delete':await remove('/admin/posts/'+id,'Hapus konten ini? Tindakan tidak dapat dibatalkan.','Konten dihapus.');break;case'service-new':editService();break;case'service-edit':editService(id);break;case'service-delete':await remove('/admin/services/'+id,'Hapus layanan ini? Layanan dengan riwayat permohonan sebaiknya dinonaktifkan.','Layanan dihapus.');break;case'user-new':editUser();break;case'user-edit':editUser(id);break;case'user-delete':await remove('/admin/users/'+id,'Hapus akun ini? Seluruh sesinya juga akan dihentikan.','Pengguna dihapus.');break;case'media-delete':await remove('/admin/media/'+id,'Hapus berkas publik ini secara permanen?','Berkas dihapus.');break;case'media-copy':{let m=S.media.find(m=>m.id===id);await copyText(m.url);break;}case'media-picker':{const media=await api('/admin/media');const filtered=media.filter(m=>b.dataset.kind!=='image'||m.mime.startsWith('image/'));if(!filtered.length){toast('Pustaka kosong. Gunakan tombol unggah di bawah isian.');break;}let existing=$('#inline-media-picker');if(existing)existing.remove();let div=document.createElement('div');div.id='inline-media-picker';div.className='note';div.innerHTML=`<b>Pilih berkas</b><div class="button-row mt">${filtered.map(m=>`<button type="button" class="btn secondary small" data-action="media-choose" data-target="${esc(b.dataset.target)}" data-url="${esc(m.url)}">${esc(m.name)}</button>`).join('')}</div>`;b.closest('.field').append(div);break;}case'media-choose':document.getElementById(b.dataset.target).value=b.dataset.url;$('#inline-media-picker')?.remove();break;case'request-open':await requestModal(id);break;case'request-delete':await remove('/admin/requests/'+id,'Hapus permohonan beserta lampiran privatnya secara permanen?','Permohonan dan lampiran dihapus.');break;case'posts-prev':adminPage--;$('#admin-post-results').innerHTML=adminPostRows();break;case'posts-next':adminPage++;$('#admin-post-results').innerHTML=adminPostRows();break;case'list-category':listCat=b.dataset.category;$$('.chip[data-action="list-category"]').forEach(x=>x.classList.toggle('active',x===b));$('#list-results').innerHTML=listResults();break;case'palette':{let p=palettes[Number(id)];['primary_color','accent_color','background_color'].forEach((k,i)=>document.getElementById('f-'+k).value=p[i+1]);applyTheme(Object.fromEntries(new FormData($('#theme-form'))));break;}case'theme-reset':applyTheme();['primary_color','accent_color','background_color'].forEach(k=>document.getElementById('f-'+k).value=S.settings[k]);break;case'copy-ticket':await copyText(ticketText());break;case'save-ticket':await downloadBlob(new Blob([ticketText()],{type:'text/plain;charset=utf-8'}),'Bukti-'+lastTicket.code+'.txt');break;case'share':await copyText(window.BPK_PREVIEW?'Buka pratinjau ini pada halaman #konten/'+id:location.href);break;case'export':{const old=b.innerHTML;b.disabled=true;b.innerHTML='Menyiapkan…';try{let dataset=b.dataset.dataset,fmt=b.dataset.format;const result=await api('/admin/export?dataset='+dataset+'&format='+fmt,{blob:true});if(window.BPK_PREVIEW&&fmt==='zip')fmt='json';await downloadBlob(result,'BPK-Kaltim-'+dataset+'.'+fmt);toast('Ekspor berhasil disiapkan.');}finally{b.disabled=false;b.innerHTML=old;}break;}case'reset-preview':if(window.BPK_PREVIEW&&confirm('Hapus semua konten, akun, unggahan, dan permohonan percobaan dari browser ini?')){await window.resetPreview();location.reload();}break;}
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();try{await handleAction(b);}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{let f=e.target.dataset.filter;switch(f){case'services':{let q=e.target.value.toLowerCase();let sv=S.services.filter(x=>(x.title+' '+x.description).toLowerCase().includes(q));$('#services-results').innerHTML=sv.length?sv.map(serviceCard).join(''):empty('Layanan tidak ditemukan','Coba kata kunci lain.','search');break;}case'public-posts':listSearch=e.target.value;$('#list-results').innerHTML=listResults();break;case'admin-posts':adminSearch=e.target.value;adminPage=1;$('#admin-post-results').innerHTML=adminPostRows();break;case'requests':requestSearch=e.target.value;$('#request-results').innerHTML=filteredRequests();break;}if(e.target.closest('#theme-form')&&e.target.type==='color')applyTheme(Object.fromEntries(new FormData($('#theme-form'))));});
document.addEventListener('change',async e=>{try{if(e.target.id==='admin-kind'){adminKind=e.target.value;adminPage=1;$('#admin-post-results').innerHTML=adminPostRows();}if(e.target.id==='request-status-filter'){requestFilter=e.target.value;$('#request-results').innerHTML=filteredRequests();}if(e.target.dataset.uploadTarget&&e.target.files[0]){const file=e.target.files[0];if(file.size>8*1024*1024)throw new Error('Maksimal 8 MB per berkas.');let f=new FormData();f.append('file',file);toast('Mengunggah berkas…');const m=await api('/admin/media',{method:'POST',body:f});document.getElementById(e.target.dataset.uploadTarget).value=m.url;toast('Unggahan selesai. Simpan formulir untuk menerapkannya.');e.target.value='';}if(e.target.id==='media-upload'&&e.target.files.length){let files=[...e.target.files];for(const file of files){if(file.size>8*1024*1024)throw new Error(file.name+' melebihi 8 MB.');let f=new FormData();f.append('file',file);await api('/admin/media',{method:'POST',body:f});}await render();toast(files.length+' berkas berhasil diunggah.');}}catch(err){toast(err.message,true);e.target.value='';}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();let submit=$('button[type="submit"]',form),old=submit?.innerHTML;const err=$('.form-error',form);if(err)err.innerHTML='';if(submit){submit.disabled=true;submit.innerHTML='Memproses…';}try{const data=Object.fromEntries(new FormData(form));switch(form.id){case'login-form':setSession(await api('/login',{method:'POST',body:data}));go('admin/dashboard');toast('Login berhasil.');break;case'post-form':data.is_demo=form.elements.is_demo.checked;await api('/admin/posts'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:data});await saveAndRefresh('Konten tersimpan.');break;case'service-form':data.active=form.elements.active.checked;data.sort_order=Number(data.sort_order);await api('/admin/services'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:data});await saveAndRefresh('Layanan tersimpan.');break;case'identity-form':data.review_mode=form.elements.review_mode.checked;await api('/admin/settings',{method:'PUT',body:data});await refresh();toast('Identitas website tersimpan.');break;case'theme-form':await api('/admin/settings',{method:'PUT',body:data});await refresh();toast('Warna website berhasil diperbarui.');break;case'user-form':data.active=form.elements.active.checked;await api('/admin/users'+(form.dataset.id?'/'+form.dataset.id:''),{method:form.dataset.id?'PUT':'POST',body:data});await saveAndRefresh('Akun pengguna tersimpan.');break;case'password-form':if(data.new_password!==data.confirm_password)throw new Error('Ulangan kata sandi tidak sama.');setSession(await api('/password',{method:'POST',body:data}));await render();toast('Kata sandi telah diganti.');break;case'request-form':{let f=new FormData(form);if((f.get('message')||'').trim().length<15)throw new Error('Jelaskan kebutuhan minimal 15 karakter.');let file=f.get('file');if(file?.size>8*1024*1024)throw new Error('Lampiran maksimal 8 MB.');f.set('consent',form.elements.consent.checked?'true':'');lastTicket=await api('/requests',{method:'POST',body:f});go('tiket');break;}case'track-form':{tracked=await api('/track',{method:'POST',body:data});tracked.credentials=data;$('#track-results').innerHTML=trackingResult(tracked);break;}case'followup-form':{if(!tracked?.credentials)throw new Error('Lakukan pelacakan kembali sebelum menambahkan tanggapan.');let f=new FormData(form);f.set('code',tracked.credentials.code);f.set('access_key',tracked.credentials.access_key);await api('/requests/followup',{method:'POST',body:f});let cred=tracked.credentials;tracked=await api('/track',{method:'POST',body:cred});tracked.credentials=cred;$('#track-results').innerHTML=trackingResult(tracked);toast('Tanggapan berhasil dikirim.');break;}case'request-admin-form':data.assigned_to=data.assigned_to?Number(data.assigned_to):null;await api('/admin/requests/'+form.dataset.id,{method:'PUT',body:data});await saveAndRefresh('Tindak lanjut tersimpan.');break;}}catch(error){if(err){err.innerHTML=`<div class="error" role="alert">${esc(error.message)}</div>`;err.scrollIntoView({block:'nearest'});}else toast(error.message,true);}finally{if(submit&&document.contains(submit)){submit.disabled=false;submit.innerHTML=old;}}});
window.addEventListener('hashchange',render);
window.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=$('.nav-links.open');if(d)d.classList.remove('open');}});
(async()=>{try{if(window.BPK_PREVIEW)await window.initPreview();const [d,session]=await Promise.all([api('/public'),api('/session')]);Object.assign(S,d);setSession(session);applyTheme();if(location.pathname==='/admin'&&!location.hash)location.hash='admin/dashboard';else await render();}catch(e){$('#app').innerHTML=`<div class="boot"><h2>Portal belum dapat dimuat.</h2><p>${esc(e.message)}</p><p>Jalankan aplikasi melalui MULAI-WINDOWS.bat, atau buka file Pratinjau_BPK_Kaltim.html.</p></div>`;}})();
// Skip navigation must not be interpreted as a page route.
document.querySelector('.skip')?.addEventListener('click',event=>{event.preventDefault();const main=document.getElementById('main');if(main){main.focus();main.scrollIntoView({block:'start'});}});
